void engine_memory_mem_pin(engine_t *m, int pin) {
    wasm_rt_memory_t *memory = w2c_engine_mem(&m->core.inst);
#if WASM_RT_USE_MMAP
    int moves = memory->is64 || memory->page_size != WASM_DEFAULT_PAGE_SIZE;
#else
    int moves = 1;
#endif
    if (!moves) return;
    long *pins = &m->mem_pins[0];
    uint64_t *saved = &m->mem_max_pages[0];
    if (pin) {
        if ((*pins)++ == 0) {
            *saved = memory->max_pages;
            memory->max_pages = memory->pages;
        }
    } else if (*pins > 0 && --(*pins) == 0) {
        memory->max_pages = *saved;
    }
}

